import { serve } from 'https://deno.land/std@0.177.0/http/server.ts';
import { createClient } from 'https://esm.sh/@supabase/supabase-js@2';

// Helper to get allowed origin from environment
const getAllowedOrigin = () => {
  const publicUrl = Deno.env.get('PUBLIC_URL');
  const allowedUrl = Deno.env.get('ALLOWED_ORIGIN');
  return publicUrl || allowedUrl || 'http://localhost:3000';
};

serve(async (req) => {
  // Handle CORS preflight request
  if (req.method === 'OPTIONS') {
    const allowedOrigin = getAllowedOrigin();
    
    return new Response('ok', {
      headers: {
        'Access-Control-Allow-Origin': allowedOrigin,
        'Access-Control-Allow-Methods': 'GET, POST, OPTIONS',
        'Access-Control-Allow-Headers':
          'Content-Type, Authorization, apikey, x-client-info',
      },
    });
  }

  try {
    const supabaseAdmin = createClient(
      Deno.env.get('SUPABASE_URL') ?? '',
      Deno.env.get('SUPABASE_SERVICE_ROLE_KEY') ?? '',
      { auth: { autoRefreshToken: false, persistSession: false } }
    );

    // Get order ID from query parameter or request body
    let orderId;
    if (req.method === 'GET') {
      const url = new URL(req.url);
      orderId = url.searchParams.get('order_id');
    } else if (req.method === 'POST') {
      const body = await req.json();
      orderId = body.order_id;
    }

    if (!orderId) {
      return new Response(JSON.stringify({ error: 'Order ID is required' }), {
        status: 400,
        headers: {
          'Content-Type': 'application/json',
          'Access-Control-Allow-Origin': getAllowedOrigin(),
        },
      });
    }

    // Fetch order status
    const { data: order, error } = await supabaseAdmin
      .from('orders')
      .select('*')
      .eq('external_order_id', orderId)
      .single();

    if (error || !order) {
      return new Response(JSON.stringify({ error: 'Order not found' }), {
        status: 404,
        headers: {
          'Content-Type': 'application/json',
          'Access-Control-Allow-Origin': getAllowedOrigin(),
        },
      });
    }

    // Fetch order items if needed
    const { data: items } = await supabaseAdmin
      .from('order_items')
      .select('*')
      .eq('order_id', order.id);

    const allowedOrigin = getAllowedOrigin();

    return new Response(JSON.stringify({
      order_id: order.external_order_id,
      status: order.status,
      payment_status: order.payment_status,
      total_amount: order.total_amount,
      customer_name: order.customer_name,
      customer_phone: order.customer_phone,
      transaction_id: order.transaction_id,
      created_at: order.created_at,
      updated_at: order.updated_at,
      items: items || []
    }), {
      headers: {
        'Content-Type': 'application/json',
        'Access-Control-Allow-Origin': allowedOrigin,
        'Access-Control-Allow-Headers': 'Content-Type, Authorization',
      },
      status: 200,
    });

  } catch (error) {
    const allowedOrigin = getAllowedOrigin();
    
    return new Response(JSON.stringify({ error: error.message }), {
      headers: {
        'Content-Type': 'application/json',
        'Access-Control-Allow-Origin': allowedOrigin,
        'Access-Control-Allow-Headers': 'Content-Type, Authorization',
      },
      status: 500,
    });
  }
});
